type Key = keyof typeof SVG;
export type UiIconName = Key extends `${infer N}:${string}` ? N : never;
export type UiIconLook = "duotone" | "glass";

/** สีตาม currentColor — กำหนดด้วย text-* ; ขนาดด้วย size-* */
export function UiIcon({ name, look = "duotone", className }: { name: UiIconName; look?: UiIconLook; className?: string }) {
  return (
    <span
      aria-hidden
      className={cn("inline-block size-6 shrink-0 [&>svg]:size-full", className)}
      // เนื้อหาเป็นค่าคงที่ที่ฝังมาตอน build (ตรวจแล้ว) ไม่ได้มาจากผู้ใช้
      dangerouslySetInnerHTML={{ __html: SVG[`${name}:${look}` as Key] }}
    />
  );
}
